const e = $('Inicio').first().json;
// adoptar_cuenta devuelve una propuesta de canal como investigar_nichos: pasa por la misma aprobación.
const clave = e.evento === 'claude_ok' ? 'claude_ok:' + ({ corregir_guion: 'guion', adoptar_cuenta: 'investigar_nichos' }[e.modo] || e.modo)
  : ['aprobado','cambios'].includes(e.evento) ? e.evento + ':' + e.etapa : e.evento;
const rutas = ["nuevo_canal", "claude_ok:investigar_nichos", "aprobado:canal", "cambios:canal", "claude_ok:crear_biblia", "nuevo_video", "claude_ok:guion", "aprobado:guion", "cambios:guion", "claude_ok:storyboard", "aprobado:storyboard", "cambios:storyboard", "claude_ok:aprender", "aprobado:final", "cambios:final", "corregir", "ajustar_biblia", "programar", "referencias", "configurar_redes", "metas", "adoptar_cuenta", "eliminar", "otro"];
const i = rutas.indexOf(clave);
return [{ json: { ...e, clave, salida: i === -1 ? rutas.length - 1 : i } }];

const r = $('Inicio').first().json.resultado || {}; const c = r.canal || {};
let critica = '';
if ($('Crítico de nichos').isExecuted) { try { const k = JSON.parse(($('Crítico de nichos').first().json.output || []).flatMap(o => o.content || []).find(x => x.type === 'output_text')?.text || '{}');
  critica = `

Crítico (GPT-6 Astra): ${k.veredicto || ''}` + ((k.sin_fuente || []).length ? '
Sin fuente: ' + k.sin_fuente.slice(0, 4).join('; ') : ''); } catch (e) { critica = ''; } }
const ev = (r.evidencia || []).slice(0, 5).map(x => '• ' + x.dato).join('
');
const temas = (r.primeros_temas || []).slice(0, 5).map(t => '– ' + t).join('
');
const dg = r.diagnostico || null; const cu = r.cuenta || null; const mt = r.metas || null;
const diag = dg ? `

Diagnóstico de la cuenta (${cu?.red || ''} ${cu?.handle || ''}):
Bien: ${(dg.bien || []).slice(0, 4).join('; ')}
Cambiar: ${(dg.cambiar || []).slice(0, 5).join('; ')}
Competencia: ${(dg.competencia || []).slice(0, 4).map(x => x.patron || x).join('; ')}` : '';
const metas = mt ? `
Metas propuestas: ${mt.videos_semana} ${mt.formato || 'videos'}/semana, tope US$${mt.gasto_semana_usd}/semana` : '';
const mensaje = `${cu ? 'Adopción de cuenta' : 'Propuesta de canal'}: ${c.nombre_propuesto}
Nicho: ${c.nicho}
Público: ${c.publico}
Promesa: ${c.promesa}${diag}${metas}

Evidencia:
${ev}

Primeros temas:
${temas}${critica}`;
const aviso = (cu ? `🧭 Adopción de ${cu.red} ${cu.handle}: ${c.nombre_propuesto}
${String((dg?.cambiar || [])[0] || c.nicho || '').slice(0, 200)}` : `🧭 Propuesta de canal: ${c.nombre_propuesto}
${String(c.nicho || '').slice(0, 200)}`) + '

Ábrelo para ver la evidencia y decidir.';
return [{ json: { dueno_email: $('Inicio').first().json.dueno_email || '', canal_id: $('Inicio').first().json.canal_id || '', etapa: 'canal', mensaje: mensaje.slice(0, 3900), aviso, contexto: r, job_id: $('Inicio').first().json.job_id } }];

const c = ($json.contexto || {}).canal || {};
const canal_id = $json.canal_id || (c.nombre_propuesto || 'canal').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0, 40) + '-' + Date.now().toString(36).slice(-4);
return [{ json: { dueno_email: $json.dueno_email || '', canal_id, nombre: c.nombre_propuesto || '', nicho: c.nicho || '', estado: 'creando_biblia', biblia_ruta: '',
  presupuesto_largo_usd: $('Leer ajustes').first().json.presupuestoLargoUsd, presupuesto_short_usd: $('Leer ajustes').first().json.presupuestoShortUsd,
  plataformas: ($json.contexto || {}).cuenta?.red || 'youtube', formato_defecto: (c.formatos || ['largo'])[0],
  // Metas del canal: las propone la adopción; un canal nuevo empieza sin producción automática.
  metas: JSON.stringify({ videos_semana: 3, formato: (c.formatos || ['short']).includes('short') ? 'short' : 'largo', gasto_semana_usd: 10, retencion_min: 0.5, auto: false, ...(($json.contexto || {}).metas || {}) }),
  cuenta: ($json.contexto || {}).cuenta ? JSON.stringify(($json.contexto || {}).cuenta) : '' } }];

const e = $json; const c = (e.contexto || {}).canal || {}; const cu = (e.contexto || {}).cuenta;
if (cu) return [{ json: { modo: 'adoptar_cuenta', canal_id: '', video_id: '', datos: { ...cu, notas: 'Cambios del operador a la propuesta anterior: ' + (e.cambios || '') + ' · Propuesta anterior: ' + JSON.stringify({ canal: c, diagnostico: e.contexto.diagnostico }).slice(0, 3000) } } }];
return [{ json: { modo:'investigar_nichos', canal_id:'', video_id:'', datos:{ criterios: e.cambios || '', rechazos:[{ nombre: c.nombre_propuesto, nicho: c.nicho, motivo: e.cambios || '' }] } } }];

// Contrato de aprendizaje: solo evidencia observada, por canal, sin credenciales.
function parseAprendizaje(raw, fallback = {}) { try { return typeof raw === 'string' ? JSON.parse(raw || 'null') ?? fallback : raw ?? fallback; } catch { return fallback; } }
function ventanaAprendizaje(publicado, ahora = Date.now()) {
  const horas = (ahora - Date.parse(publicado || '')) / 3600000;
  return horas >= 168 ? '7d' : horas >= 72 ? '72h' : horas >= 24 ? '24h' : null;
}
function metricasAprendizaje(m) {
  const numero = v => v !== null && v !== '' && v !== undefined && Number.isFinite(Number(v)) && Number(v) >= 0 ? Number(v) : null;
  return Object.fromEntries(['vistas','meGusta','comentarios','retencion','seguidoresGanados'].map(k => [k, numero(m?.[k])]));
}
function contextoAprendizaje(video, trabajos, planos) {
  const propios = trabajos.filter(t => t.video_id === video.video_id && t.canal_id === video.canal_id && ['ok','listo'].includes(t.estado)).sort((a,b) => String(b.updatedAt || b.createdAt).localeCompare(String(a.updatedAt || a.createdAt)));
  const resultado = modo => { const r = parseAprendizaje(propios.find(t => modo.includes(t.modo))?.resultado); return r.resultado || r; };
  const guion = resultado(['guion','corregir_guion']), storyboard = resultado(['storyboard']);
  return { titulo: String(guion.titulo || video.tema || '').slice(0,500), guion: typeof guion.guion === 'string' ? guion.guion.slice(0,10000) : null, extracto_acotado:true,
    planos: (storyboard.planos || planos.filter(p => p.video_id === video.video_id).map(p => parseAprendizaje(p.plano, p))).slice(0,80).map(p => ({ id:String(p.id || p.plano_id || ''), texto:String(p.texto_narrado || '').slice(0,500), duracion_s:Number(p.duracion_s) || null, encuadre:String(p.encuadre || '').slice(0,100), texto_pantalla:String(p.texto_pantalla || '').slice(0,200) })),
    miniatura: storyboard.miniatura ? { texto:String(storyboard.miniatura.texto || '').slice(0,200), descripcion:String(storyboard.miniatura.prompt_imagen || '').slice(0,2000) } : null };
}
function acotarEvidenciasAprendizaje(nuevas, anteriores) {
  const vistas=new Set(), salida=[]; let longitud=0;
  for(const e of [...nuevas,...anteriores]) {
    const id=[e.video_id,e.red,e.ventana].join(':'), cantidad=JSON.stringify(e).length;
    if(vistas.has(id) || longitud+cantidad>160000 || salida.length>=12) continue;
    vistas.add(id);salida.push(e);longitud+=cantidad;
  }
  return salida;
}
function validarAprendizaje(resultado, contexto, jobId) {
  const evidencias = Array.isArray(contexto?.evidencias) ? contexto.evidencias : [];
  const texto = (s,n=1500) => String(s || '').slice(0,n);
  const lecciones = (Array.isArray(resultado?.lecciones) ? resultado.lecciones : []).slice(0,30).flatMap((l,i) => {
    const refs = (Array.isArray(l.origenes) ? l.origenes : []).flatMap(o => {
      const e = evidencias.find(e => e.video_id === o.video_id && e.red === o.red && e.ventana === o.ventana);
      if (!e || !['vistas','meGusta','comentarios','retencion','seguidoresGanados'].includes(o.metrica) || e.metricas[o.metrica] === null || e.metricas[o.metrica] === undefined) return [];
      // El valor procede del registro, nunca de la respuesta del modelo.
      return [{ video_id:e.video_id, red:e.red, ventana:e.ventana, fecha:e.fecha, metrica:o.metrica, valor:e.metricas[o.metrica], demora_horas:e.demora_horas || 0 }];
    });
    if (!refs.length || !texto(l.regla).trim() || !texto(l.causa).trim() || !texto(l.correccion).trim()) return [];
    return [{ id:jobId + ':' + i, regla:texto(l.regla,500), causa:texto(l.causa), correccion:texto(l.correccion), origenes:refs.slice(0,20),
      nivel:new Set(refs.map(o=>o.video_id)).size >= 3 ? 'patron' : 'hipotesis', estado:'propuesta', aplicada_en:[] }];
  });
  return { resumen:texto(resultado?.resumen,3000), lecciones, evidencia_version:1 };
}
function leccionesParaGuion(trabajos, canal) {
  return trabajos.filter(t => t.canal_id === canal && t.modo === 'aprender' && ['ok','listo'].includes(t.estado)).sort((a,b) => String(b.updatedAt || b.createdAt).localeCompare(String(a.updatedAt || a.createdAt))).flatMap(t => {
    const r=parseAprendizaje(t.resultado); return (r.resultado?.evidencia_version === 1 ? r.resultado.lecciones : []).filter(l=>l.id && l.origenes?.length);
  }).slice(0,30);
}

const e = $('Inicio').first().json; const canal = $('Canal con competencia').isExecuted ? $('Canal con competencia').first().json : $('Buscar canal').first().json;
const biblia = (JSON.parse($('Buscar biblia').first().json.resultado || '{}').resultado) || {};
// Sin tema: la fábrica lo elige (vidIQ investiga el nicho y el guionista elige sin repetir los temas recientes).
const modo_noticia = typeof e.modo_noticia === 'boolean' ? e.modo_noticia : canal.modo_noticia === true;
const lecciones=leccionesParaGuion($('Lecciones antes del guion').all().map(i=>i.json),canal.canal_id); biblia.lecciones_automaticas=lecciones;
const elegir = !String(e.tema || '').trim();
const recientes = $('Temas recientes del canal').all().map(i => i.json).filter(v => v.video_id && v.tema).sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt))).slice(0, 30).map(v => v.tema);
const formato = e.formato || canal.formato_defecto || 'largo';
const video_id = e.video_id || 'v-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 6);
const presupuesto = formato === 'short' ? canal.presupuesto_short_usd : canal.presupuesto_largo_usd;
return [{ json: { fila: { modo_noticia, noticia:'', noticia_guion_hash:'', noticia_storyboard_hash:'', dueno_email: canal.dueno_email || '', presentacion: JSON.stringify(e.presentacion || null), cooper_orden_id: e.cooper_orden_id || '', video_id, canal_id: canal.canal_id, tema: elegir ? '(la fábrica elige el tema)' : String(e.tema || '').slice(0, 500), formato, etapa: modo_noticia ? 'radar' : 'guion', estado: 'en_proceso',
  version: 1, costo_usd: 0, presupuesto_usd: presupuesto, drive_carpeta: '', youtube_id: '', intentos: 0, error: '' },
  pedido: { modo: 'guion', canal_id: canal.canal_id, video_id, datos: { modo_noticia, presentacion: e.presentacion || null, tema: elegir ? '' : e.tema, elegir_tema: elegir, temas_recientes: recientes,
    competencia: (()=>{try{return JSON.parse(canal.tendencias||'{}').competencia||null;}catch{return null;}})(), aprendizaje:{lecciones,obligatorio:true,instrucciones:'Lee todas las lecciones. Devuelve aprendizajes_aplicados [{id,cambio,motivo_no_aplica}]; las hipótesis son experimentos, no hechos. No copies datos de otras cuentas.'}, nicho: canal.nicho || '', formato, biblia, tendencias: (() => { try { const t = JSON.parse(canal.tendencias || '{}'); return Date.now() - Date.parse(t.fecha || 0) < 3 * 86400000 ? t : null; } catch (x) { return null; } })(),
    duracion_objetivo_s: formato === 'short' ? 50 : 540, vidiq: e.vidiq === 'use' ? 'use' : 'skip',
    indicaciones: String(e.indicaciones || '').slice(0, 2000), documental_url: String(e.documental_url || '') } } } }];

// La investigación de palabras clave necesita una semilla corta (2–4 palabras); con la frase entera vidIQ devolvía volumen nulo.
const p = $('Nuevo video').first().json.pedido;
const vacias = new Set('a al como cómo con cuanto cuánto de del el en es la las lo los mas más para por que qué se su sus un una uno y o verdad realmente gana ganan cuesta hoy'.split(' '));
const semilla = String(p.datos.tema || p.datos.nicho || '').toLowerCase().normalize('NFC').replace(/[¿?¡!.,:;«»"()]/g, ' ').split(/\s+/).filter(w => w.length > 2 && !vacias.has(w)).slice(0, 3).join(' ');
return [{ json: { accion: 'investigar', tema: p.datos.tema || semilla, semilla: semilla || p.datos.tema, formato: p.datos.formato, idioma: $('Leer ajustes').first().json.idioma } }];

// El guion recibe lo que encontró vidIQ (palabras clave y videos que destacan) como contexto, si se usó.
const p = $('Nuevo video').first().json.pedido;
if (p.datos.modo_noticia) { const n=$('Buscar noticia verificada').first().json.noticia; return [{json:{...p,datos:{...p.datos,tema:n.titulo,elegir_tema:false,noticia:n,indicaciones:'Cuenta solo los hechos verificados, cita sus fuentes y fecha. No añadas cifras ni afirmaciones nuevas. Propón únicamente mapas, cifras y esquemas propios generados, nunca imágenes de medios.'}}}]; }
const vq = $('vidIQ: investigar').isExecuted ? $('vidIQ: investigar').first().json : null;
return [{ json: { ...p, datos: { ...p.datos, ...(vq?.ok ? { vidiq: 'datos', investigacion_vidiq: { palabras_clave: vq.palabras_clave, videos_destacados: vq.videos_destacados } } : {}) } } }];

// Topes de 24 h: por canal y de toda la fábrica. Si se pasan, el video no se crea y te avisa.
const aj = $('Leer ajustes').first().json; const canal = $('Buscar canal').first().json.canal_id;
const v = $input.all().map(i => i.json).filter(x => x.video_id);
const delCanal = v.filter(x => x.canal_id === canal).length;
const motivo = delCanal >= aj.maxVideosDiaPorCanal ? `el canal ${canal} ya tiene ${delCanal} videos nuevos en 24 h (tope ${aj.maxVideosDiaPorCanal})`
  : v.length >= aj.maxVideosDiaTotal ? `la fábrica ya creó ${v.length} videos en 24 h (tope ${aj.maxVideosDiaTotal})` : '';
return [{ json: { ok: !motivo, motivo } }];

const GANCHOS = {"formulas": [{"id": "el-dato", "nombre": "El dato", "forma": "Un número que el espectador no sabía, dicho seco, y su consecuencia.", "ejemplo": "De cada 10 soles que pagas en el grifo, solo 2 se quedan en el grifo.", "falla": "Muere si el número es vago o no se puede comprobar. Di la fuente.", "patrones": ["\\b\\d+([.,]\\d+)?\\s?%", "\\b\\d+ (de|en) (cada )?\\d+\\b", "\\bde cada \\d+\\b", "\\bs/ ?\\d", "\\bde (tus|tu|sus|cada) \\d+\\b", "\\d+ (mil|soles|millones)?.*(y|pero) .*\\d+"]}, {"id": "resultado-ajeno", "nombre": "El resultado de otro", "forma": "El resultado de alguien con nombre o un negocio concreto, y luego el mecanismo.", "ejemplo": "Esta pollería vende 70 mil al mes y al dueño le quedan 7 mil. Hice la cuenta.", "falla": "No inventes el número. Si no puedes nombrar el caso, usa otra fórmula.", "patrones": ["\\beste (negocio|grifo|local|restaurante|canal|senor|dueno)\\b", "\\besta (polleria|bodega|tienda|empresa|senora)\\b", "\\bpaso de .* a\\b", "\\ben (un|una|dos|tres|\\d+) (semana|mes|ano)s?\\b"]}, {"id": "el-error", "nombre": "El error", "forma": "Nombra el error que el espectador probablemente comete ahora mismo.", "ejemplo": "Crees que el grifo te roba en el precio. El margen está en otro lado.", "falla": "Solo funciona si el error es común y se comprueba en un segundo.", "patrones": ["\\b(estas|sigues) (haciendo|cometiendo|pagando)\\b", "\\bel (error|motivo) (que )?(todos|casi todos|nadie)\\b", "\\bdeja de\\b", "\\bcrees que\\b"]}, {"id": "contra-corriente", "nombre": "Contra la corriente", "forma": "Di el consejo que todos aceptan y recházalo.", "ejemplo": "Todos dicen que el grifo gana con la gasolina. Gana con lo que vende al lado.", "falla": "Necesita la prueba en los 15 segundos siguientes o suena a llevar la contraria por gusto.", "patrones": ["\\btodos (dicen|creen|piensan|te dicen)\\b", "\\bes (en realidad )?(mentira|falso)\\b", "\\bnadie (te dice|habla de|te cuenta)\\b", "\\bno es (por|lo que)\\b"]}, {"id": "la-revelacion"